# slug -> display label, read from the embedded manifest (no geocoding at runtime).
LOCATIONS: dict[str, str] = {slug: entry.label for slug, entry in _CACHE.items()}
DEFAULT_LOCATION = next(iter(LOCATIONS), "")

# Original presets in indah's Studio palette (ADR-0014) - distinct names and color
# roles from prettymapp's Peach/Auburn/Citrus/Flannel, per the licensing decision above.
THEMES: dict[str, dict[str, str]] = {
    "Porcelain": {
        "bg": "#fdf6ee",
        "street": "#2e6d62",
        "building": "#b5296b",
        "water": "#8fb4c9",
        "green": "#9fae7e",
        "ink": "#2b2320",
    },
    "Noir": {
        "bg": "#191512",
        "street": "#e9e2d8",
        "building": "#e0567e",
        "water": "#5b7aa8",
        "green": "#4f8f78",
        "ink": "#f3ece2",
    },
    "Terracotta": {
        "bg": "#f6ece1",
        "street": "#7a3b2e",
        "building": "#c76b4a",
        "water": "#9cc0c9",
        "green": "#7c8f5e",
        "ink": "#3d241c",
    },
    "Slate": {
        "bg": "#eef0f2",
        "street": "#33475b",
        "building": "#5a728c",
        "water": "#7fa7c9",
        "green": "#7f9e78",
        "ink": "#22303c",
    },
}
SHAPES = ["Circle", "Square"]

_decoded: dict[str, dict[str, Any]] = {}


def _load(slug: str) -> dict[str, Any]:
    """Decode one location's geometry, lazily and once (gzip+base64 -> JSON)."""
    if slug not in _decoded:
        raw = gzip.decompress(base64.b64decode(_CACHE[slug].gz_b64))
        _decoded[slug] = json.loads(raw)
    return _decoded[slug]


def _bbox(data: dict[str, Any]) -> tuple[float, float, float, float]:
    """The natural (lon, lat) extent of the fetched shapes, padded a little."""
    xs: list[float] = []
    ys: list[float] = []
    for key in ("streets", "buildings", "water", "green"):
        for shape in data[key]:
            for x, y in shape:
                xs.append(x)
                ys.append(y)
    if not xs:
        lat0, lon0 = data["center"]
        return lon0 - 0.01, lon0 + 0.01, lat0 - 0.01, lat0 + 0.01
    pad_x = (max(xs) - min(xs)) * 0.04
    pad_y = (max(ys) - min(ys)) * 0.04
    return min(xs) - pad_x, max(xs) + pad_x, min(ys) - pad_y, max(ys) + pad_y


def _circle_frame(cx: float, cy: float, rx: float, ry: float, lat0: float, **kw) -> Any:
    """A screen-circular frame in (lon, lat) data space.

    A plain ``Circle`` patch uses one radius for both axes in *data* units, but a
    degree of longitude and a degree of latitude aren't the same real distance away
    from the equator - drawn under the ``1 / cos(lat)`` axes correction below, an
    equal-data-radius circle comes out as a tall ellipse on screen. ``Ellipse`` with
    a matching width/height ratio compensates, so it reads as a true circle.
    """
    from matplotlib.patches import Ellipse

    cos_lat = math.cos(math.radians(lat0))
    half_lon = min(rx, ry / cos_lat)  # the largest true circle that fits the bbox
    half_lat = half_lon * cos_lat
    return Ellipse((cx, cy), width=2 * half_lon, height=2 * half_lat, **kw)


def render_poster(slug: str, theme: str, shape: str):
    """Render one location's cached OSM geometry as a styled matplotlib Figure."""
    import matplotlib

    matplotlib.use("Agg")  # a server has no display; also skips pyplot's global state
    from matplotlib.collections import LineCollection, PolyCollection
    from matplotlib.figure import Figure
    from matplotlib.patches import Rectangle as RectPatch

    data = _load(slug)
    t = THEMES.get(theme, THEMES["Porcelain"])
    lat0, lon0 = data["center"]
    x0, x1, y0, y1 = _bbox(data)
    cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
    rx, ry = (x1 - x0) / 2, (y1 - y0) / 2

    fig = Figure(figsize=(6, 6.8), dpi=150)
    ax = fig.add_subplot(111)
    fig.patch.set_facecolor(t["bg"])
    ax.set_facecolor(t["bg"])
    ax.set_xlim(x0, x1)
    ax.set_ylim(y0, y1)
    # A local equirectangular correction: 1 degree of longitude is cos(lat) degrees'
    # worth of real distance shorter than 1 degree of latitude at this latitude, so
    # without this the frame would look horizontally stretched or squeezed.
    ax.set_aspect(1 / math.cos(math.radians(lat0)))
    ax.axis("off")
    ax.margins(0)

    frame: Any = (
        _circle_frame(cx, cy, rx, ry, lat0)
        if shape == "Circle"
        else RectPatch((x0, y0), x1 - x0, y1 - y0)
    )
    ax.add_patch(frame)
    frame.set_facecolor(t["bg"])
    frame.set_edgecolor("none")
    frame.set_zorder(0)

    if data["water"]:
        coll = PolyCollection(data["water"], facecolor=t["water"], edgecolor="none", zorder=1)
        coll.set_clip_path(frame)
        ax.add_collection(coll)
    if data["green"]:
        coll = PolyCollection(
            data["green"], facecolor=t["green"], edgecolor="none", alpha=0.65, zorder=2
        )
        coll.set_clip_path(frame)
        ax.add_collection(coll)
    if data["buildings"]:
        coll = PolyCollection(
            data["buildings"], facecolor=t["building"], edgecolor="none", alpha=0.88, zorder=3
        )
        coll.set_clip_path(frame)
        ax.add_collection(coll)
    if data["streets"]:
        coll = LineCollection(data["streets"], colors=t["street"], linewidths=1.2, zorder=4)
        coll.set_clip_path(frame)
        ax.add_collection(coll)

    outline = (
        _circle_frame(cx, cy, rx, ry, lat0, fill=False, edgecolor=t["ink"], linewidth=2.2, zorder=5)
        if shape == "Circle"
        else RectPatch(
            (x0, y0), x1 - x0, y1 - y0, fill=False, edgecolor=t["ink"], linewidth=2.2, zorder=5
        )
    )
    ax.add_patch(outline)

    fig.text(
        0.5,
        0.06,
        LOCATIONS.get(slug, slug),
        ha="center",
        fontsize=15,
        fontweight="bold",
        color=t["ink"],
        family="serif",
    )
    fig.text(
        0.5,
        0.025,
        f"{theme} - made with indah - {data['attribution']}",
        ha="center",
        fontsize=7.5,
        color=t["ink"],
        alpha=0.75,
    )
    fig.subplots_adjust(left=0.03, right=0.97, top=0.97, bottom=0.14)
    return fig


def build() -> indah.Session:
    location = indah.Signal(DEFAULT_LOCATION)
    theme = indah.Signal("Porcelain")
    shape = indah.Signal("Circle")

    def poster():
        return render_poster(location.value, theme.value, shape.value)

    controls = indah.Card(
        title="Map",
        children=[
            indah.Select(
                location,
                options=[(slug, label) for slug, label in LOCATIONS.items()],
                label="Place",
            ),
            indah.Select(theme, options=list(THEMES), label="Theme"),
            indah.Radio(shape, options=SHAPES, label="Frame"),
            indah.Download(
                lambda: indah.DownloadFile(
                    _svg_bytes(location.value, theme.value, shape.value),
                    filename=f"{location.value}.svg",
                    media_type="image/svg+xml",
                ),
                label="Download map (SVG)",
            ),
        ],
    )

    preview = indah.Card(children=[indah.Plot(poster, alt="map poster")])

    intro = indah.Text(
        "# Map poster\n\n"
        "Pick a neighborhood, restyle it, and it re-renders live from real "
        "OpenStreetMap street, building, water, and park data - reactive, so only "
        "the image patches. Then **download** it as an SVG. The public gallery "
        "sticks to this curated list rather than an arbitrary address (see the "
        "module docstring for why); the fetch script that built this cache works "
        "for any place.",
        markdown=True,
    )
    return indah.Session(
        indah.Column(children=[intro, indah.Sidebar(children=[controls, preview])])
    )


def _svg_bytes(slug: str, theme: str, shape: str) -> bytes:
    import io

    fig = render_poster(slug, theme, shape)
    buffer = io.BytesIO()
    fig.savefig(buffer, format="svg", bbox_inches="tight")
    return buffer.getvalue()


app = indah.create_app(session_factory=build)

if __name__ == "__main__":
    indah.launch(app)
